// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DepositLog c;

    function setUp() public {
        c = new DepositLog();
    }

    function _run(address requester, bytes32 digest, uint256 utxoSize, bytes memory redeemerOutputScript, uint256 requestedFee, bytes memory outpoint) internal {
        bool obs = c.logRedemptionRequested(requester, digest, utxoSize, redeemerOutputScript, requestedFee, outpoint);
        assertTrue(obs == c.approvedLoggers(address(this)));
    }

    function testFuzz_run(address requester, bytes32 digest, uint256 utxoSize, bytes memory redeemerOutputScript, uint256 requestedFee, bytes memory outpoint) public {
        vm.assume(requester.code.length == 0 && uint160(requester) > 0xffff && requester != address(this) && requester != address(c) && requester != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && requester != 0x000000000000000000636F6e736F6c652e6c6f67 && requester != 0x4e59b44847b379578588920cA78FbF26c0B4956C && requester != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(requester, digest, utxoSize, redeemerOutputScript, requestedFee, outpoint);
    }

    receive() external payable { }
}
